text(await tools.exec_command({cmd:"@'
from pathlib import Path
import json,collections,importlib.util
root=Path('D:/4A/01_便签店运营_2026-10');imgs=root/'02_Listing与新图包';out=Path('work/4a-reclass-20261031')
summary={}
for section in ['03_视频素材与成品','05_历史版本与中间过程']:
 files=[x for x in (root/section).rglob('*') if x.is_file()]
 summary[section]={'files':len(files),'types':dict(collections.Counter(x.suffix.lower() for x in files))}
selected=[x for x in imgs.rglob('*') if x.is_file() and any(n in x.parts for n in ['原图参考','生成源图','_核验依据'])]
summary['target_source_content']={'files':len(selected),'types':dict(collections.Counter(x.suffix.lower() for x in selected))}
summary['manifests']=[]
for f in imgs.glob('0[1-6]*/*/manifest.json'):
 d=json.loads(f.read_text(encoding='utf-8-sig')); im=d.get('images',[])
 summary['manifests'].append({'file':str(f.relative_to(imgs)),'image_count':len(im),'upload_approved_true':sum(x.get('approved_for_upload') is True for x in im),'upload_approved_false':sum(x.get('approved_for_upload') is False for x in im),'status':dict(collections.Counter(x.get('status','MISSING') for x in im)),'refs':len(d.get('reference_files',[]))})
summary['editable_files']=[str(x.relative_to(imgs)) for x in selected if x.suffix.lower() in ['.svg','.py','.cjs','.mjs','.js','.psd','.blend','.aep','.prproj']]
summary['cv2']=bool(importlib.util.find_spec('cv2'))
(out/'gemini-content-evidence.json').write_text(json.dumps(summary,ensure_ascii=False,indent=2),encoding='utf-8')
print(json.dumps(summary,ensure_ascii=False,indent=2))
'@ | python -","max_output_tokens":6500}));

